-- Schéma de la v1 (tables de public), généré par `dotnet ef migrations script` sur le code v1 (src/back) le 16/10/2026,
-- juste avant sa suppression (I2, #236). Figé : la v1 ne change plus. Base de forme v1 des tests de l'import (ImportDatabase).

CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "DailyChallenges" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" date NOT NULL,
    "Seed" integer NOT NULL,
    CONSTRAINT "PK_DailyChallenges" PRIMARY KEY ("Id")
);

CREATE TABLE "Players" (
    "Id" uuid NOT NULL,
    "IsGuest" boolean NOT NULL DEFAULT FALSE,
    "Pseudo" character varying(20),
    "Email" character varying(256),
    "AuthToken" uuid NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (now() at time zone 'utc'),
    "LastSeenAt" timestamp with time zone,
    "IsDeleted" boolean NOT NULL DEFAULT FALSE,
    "DeletedAt" timestamp with time zone,
    CONSTRAINT "PK_Players" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Players_GuestPseudo" CHECK (("IsGuest" = true AND "Pseudo" IS NULL) OR ("IsGuest" = false AND "Pseudo" IS NOT NULL))
);

CREATE TABLE "Settings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(100) NOT NULL,
    "Value" character varying(1000) NOT NULL,
    "Description" character varying(500),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (now() at time zone 'utc'),
    CONSTRAINT "PK_Settings" PRIMARY KEY ("Id")
);

CREATE TABLE "Tracks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DeezerTrackId" bigint NOT NULL,
    "Artist" character varying(200) NOT NULL,
    "Title" character varying(300) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (now() at time zone 'utc'),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Tracks" PRIMARY KEY ("Id")
);

CREATE TABLE "GameSessions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" uuid NOT NULL,
    "DailyChallengeId" integer NOT NULL,
    "TotalScore" integer NOT NULL,
    "TotalDurationSeconds" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (now() at time zone 'utc'),
    CONSTRAINT "PK_GameSessions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_GameSessions_DailyChallenges_DailyChallengeId" FOREIGN KEY ("DailyChallengeId") REFERENCES "DailyChallenges" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_GameSessions_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);

CREATE TABLE "DailyChallengeTracks" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DailyChallengeId" integer NOT NULL,
    "TrackId" integer NOT NULL,
    "DeezerRankSnapshot" integer NOT NULL,
    "Position" integer NOT NULL,
    CONSTRAINT "PK_DailyChallengeTracks" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DailyChallengeTracks_DailyChallenges_DailyChallengeId" FOREIGN KEY ("DailyChallengeId") REFERENCES "DailyChallenges" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_DailyChallengeTracks_Tracks_TrackId" FOREIGN KEY ("TrackId") REFERENCES "Tracks" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "GameSessionAnswers" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "GameSessionId" integer NOT NULL,
    "DailyChallengeTrackId" integer NOT NULL,
    "ListenedDurationSeconds" integer NOT NULL,
    "WasExtended" boolean NOT NULL,
    "ArtistAnswer" character varying(200),
    "TitleAnswer" character varying(300),
    "ArtistCorrect" boolean NOT NULL,
    "TitleCorrect" boolean NOT NULL,
    "Score" integer NOT NULL,
    CONSTRAINT "PK_GameSessionAnswers" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_GameSessionAnswers_DailyChallengeTracks_DailyChallengeTrack~" FOREIGN KEY ("DailyChallengeTrackId") REFERENCES "DailyChallengeTracks" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_GameSessionAnswers_GameSessions_GameSessionId" FOREIGN KEY ("GameSessionId") REFERENCES "GameSessions" ("Id") ON DELETE CASCADE
);

