INSERT INTO "Settings" ("Id", "Description", "Key", "UpdatedAt", "Value")
VALUES (7, 'Nombre de jours avant qu''un morceau déjà utilisé redevienne éligible à la génération.', 'TrackCooldownDays', TIMESTAMPTZ '2026-01-01T00:00:00Z', '30');

UPDATE "Tracks" t
SET "LastUsedDate" = agg."MaxDate",
    "UsageCount"   = agg."UsageCount"
FROM (
    SELECT dct."TrackId" AS "TrackId",
           MAX(dc."Date") AS "MaxDate",
           COUNT(*)       AS "UsageCount"
    FROM "DailyChallengeTracks" dct
    JOIN "DailyChallenges" dc ON dc."Id" = dct."DailyChallengeId"
    GROUP BY dct."TrackId"
) agg
WHERE t."Id" = agg."TrackId";

